sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var requestBody = request.body.data;
    var eventId = requestBody.eventId;
    var taskName = requestBody.taskName;
    var assignedTo = requestBody.assignedTo;
    var dueDate = requestBody.dueDate;

    if (!eventId || !taskName || !dueDate) {
        response.setStatus(400);
        return response.setBody({ error: "Missing required fields" });
    }

    var _eventGR = new GlideRecordSecure('x_1610434_event_0_event_record');
	_eventGR.addQuery('number', eventId);
	_eventGR.query();

    if (!_eventGR.next()) {
        response.setStatus(404);
        return response.setBody({ error: "Event ID not found" });
    }

    var _taskGR = new GlideRecordSecure('x_1610434_event_0_event_task');
    _taskGR.initialize();
    _taskGR.setValue('event_id', eventId);
    _taskGR.setValue('task_name', taskName);
    _taskGR.setValue('due_date', dueDate);

    if (assignedTo) {
        var _userGR = new GlideRecordSecure('sys_user');
		_userGR.addQuery('user_name', assignedTo);
		_userGR.query();

        if (_userGR.next()) {
            _taskGR.setValue('assigned_to', _userGR.getUniqueValue());
        } else {
            response.setStatus(404);
            return response.setBody({ error: "Assigned user not found" });
        }
    }

    _taskGR.insert();

    response.setStatus(201);
    return response.setBody({
        message: "Task created successfully",
        taskId: _taskGR.getUniqueValue()
    });

})(request, response);
